const KIND_ORDER = ['Sacred status','City','Land or layer','Site','Mīqāt','Hadith place','Named limit','Ḥaram marker','View','Road'];
function searchPlaces(q){
  const nq = norm(q); if(!nq) return [];
  const toks = nq.split(' ');
  const out = [];
  for(const e of INDEX){
    const words = e.t.split(' '), lw = e.n.split(' '), lj = e.n.replace(/ /g,''), qj = nq.replace(/ /g,'');
    const wordHit = t => words.some(w=>w.startsWith(t) || (t.length>=3 && w.includes(t)));
    if(!(toks.every(wordHit) || (qj.length>=3 && lj.includes(qj)))) continue;
    /* exact word in the name, then name starts with it, then a word starts with it, then inside the name, then only in aliases */
    const sc = toks.every(t=>lw.includes(t)) ? 0 : e.n.startsWith(nq) ? 1 : toks.every(t=>lw.some(w=>w.startsWith(t))) ? 2 : lj.includes(qj) ? 3 : 4;
    out.push({e, sc});
  }
  out.sort((a,b)=>a.sc-b.sc || KIND_ORDER.indexOf(a.e.kind)-KIND_ORDER.indexOf(b.e.kind) || a.e.rank-b.e.rank || a.e.label.length-b.e.label.length);   /* rank: a city's map priority, so Madinah comes before Madrid */
  const seen = new Set();
  return out.filter(o=>{ const k = o.e.kind+'|'+o.e.label; if(seen.has(k)) return false; seen.add(k); return true; }).slice(0, 8).map(o=>o.e);
}
const qEl = document.getElementById('placeq'), listEl = document.getElementById('placelist');
let hits = [], active = -1;
const esc = s => s.replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function renderHits(){
  if(!qEl.value.trim()){ listEl.hidden = true; qEl.setAttribute('aria-expanded','false'); return; }
  listEl.innerHTML = hits.length ? hits.map((e,i)=>`<li role="option" id="po-${i}" data-i="${i}" aria-selected="${i===active}"><b>${esc(e.label)}</b><span>${esc(e.kind)}${e.sub?' · '+esc(e.sub):''}</span></li>`).join('')
    : `<li class="none" role="option" aria-disabled="true">No place by that name on this map</li>`;
  listEl.hidden = false; qEl.setAttribute('aria-expanded','true');
  if(active>=0) qEl.setAttribute('aria-activedescendant', 'po-'+active); else qEl.removeAttribute('aria-activedescendant');
}
function pick(i){ const e = hits[i]; if(!e) return; qEl.value = e.label; listEl.hidden = true; qEl.setAttribute('aria-expanded','false'); qEl.blur(); e.act(); }
qEl.addEventListener('input', ()=>{ hits = searchPlaces(qEl.value); active = hits.length ? 0 : -1; renderHits(); });
qEl.addEventListener('focus', ()=>{ if(qEl.value.trim()){ hits = searchPlaces(qEl.value); renderHits(); } });
qEl.addEventListener('keydown', e=>{
  if(e.key==='ArrowDown'){ e.preventDefault(); if(hits.length){ active = (active+1) % hits.length; renderHits(); } }
  else if(e.key==='ArrowUp'){ e.preventDefault(); if(hits.length){ active = (active-1+hits.length) % hits.length; renderHits(); } }
  else if(e.key==='Enter'){ e.preventDefault(); pick(active>=0 ? active : 0); }
  else if(e.key==='Escape'){ listEl.hidden = true; qEl.setAttribute('aria-expanded','false'); }
});
listEl.addEventListener('pointerdown', e=>{ const li = e.target.closest('li[data-i]'); if(li){ e.preventDefault(); pick(+li.dataset.i); } });
document.addEventListener('pointerdown', e=>{ if(!e.target.closest('.find')){ listEl.hidden = true; qEl.setAttribute('aria-expanded','false'); } });

/* ---------------- links to a place ---------------- */
function tokenFor(key){
  if(/^st\d+$/.test(key)) return key;
  if(/^lim_[A-P]$/.test(key)) return 'lim-'+key.slice(4).toLowerCase();
  /* the overlays open with their layer switched on */
  if(key === 'natb') return 'natural-line';
  if(key === 'intl') return 'internal-lines';
  return /^[a-z0-9_]+$/i.test(key) ? key : null;
}
const OLD_HASH = {makkah:[4,'makkah'], madinah:[5,'madinah'], jerusalem:[3,'aqsa'], sham:[1,'sham'], miqat:[6,'miqat'], hijaz:[7,'hijaz']};
function openToken(tok, first){
  if(!tok || !/^[A-Za-z0-9._~-]+$/.test(tok)) return;
  if(/^(fullmap|full|full-map|fullscreen)$/i.test(tok)) return enterFull(!first);
  if(document.getElementById(tok)) return;   /* a section anchor, not a place */
  let t = tok.toLowerCase(), m;
  const run = f => first ? setTimeout(f, 350) : f();
  if((m = t.match(/^st(\d{1,2})$/))) return run(()=>goStatus(+m[1], true));
  if((m = t.match(/^lim-([a-p])$/))) return run(()=>goLimit(m[1].toUpperCase()));
  /* Version 66: the outlines are numbered from the smallest (V1) to the largest (V7); the older names still open them */
  const OUTLINE_TOK = {'outline-v1':'me', 'outline-middle-east':'me', 'outline-v4':'me2', 'outline-v3':'west', 'outline-iraq':'west', 'outline-v2':'full', 'outline-v2n':'full', 'outline-v2-b':'fullb', 'outline-v2b':'fullb', 'outline-v2-natural':'full', 'outline-complete':'full', 'outline-v5':'v3', 'outline-complete-v3':'v3', 'outline-v6':'v2', 'outline-greater-middle-east':'v2', 'outline-v7':'gme', 'outline-greater':'gme', 'outline-gme':'gme'};   /* Version 68 added a version; Version 71 reordered them by size again (the Nile lands in V1 and V4) */
  if(OUTLINE_TOK[t]) return run(()=>openOutline(OUTLINE_TOK[t]));
  if((m = t.match(/^who-(rev|early|geo|modern)$/))) return run(()=>{ setTier(m[1]==='geo' ? 'classical' : m[1]); scrollToMap(); });
  if(OLD_HASH[t]) return run(()=>{ goFocus(OLD_HASH[t][0]); select(OLD_HASH[t][1]); scrollToMap(); });
  const hit = INDEX.find(e=>e.keys.includes(t)) || INDEX.find(e=>e.n.replace(/ /g,'-')===t);
  if(hit) return run(()=>{ hit.act(); scrollToMap(); });
  if(INFO[t]) return run(()=>select(t));
}
window.addEventListener('hashchange', ()=>openToken(location.hash.slice(1)));
/* a copy-link button on every note */
const _showInfo = showInfo;
showInfo = function(key, extraTitle){
  _showInfo(key, extraTitle);
  let tok = tokenFor(key); if(!tok || key==='intro') return;
  if(key === 'caliphx' || key === 'caliphg') tok = 'outline-' + XNUM[XV].toLowerCase();
  const url = `${ART_URL}#${tok}`;
  const box = document.createElement('div'); box.className = 'sharebox';
  box.innerHTML = `<button type="button" class="linkbtn copyl">Copy a link to this note</button><input type="text" readonly value="${url}" aria-label="Link to this note" hidden>`;
  const refs = infoEl.querySelector('.refs'); refs ? infoEl.insertBefore(box, refs) : infoEl.appendChild(box);
  const btn = box.querySelector('button'), inp = box.querySelector('input');
  btn.addEventListener('click', ()=>{
    const fallback = ()=>{ inp.hidden = false; inp.focus(); inp.select(); btn.textContent = 'Copy this link:'; };
    try { navigator.clipboard.writeText(url).then(()=>{ btn.textContent = 'Link copied'; setTimeout(()=>{ btn.textContent = 'Copy a link to this note'; }, 2200); }, fallback); } catch(e){ fallback(); }
  });
};

/* ---------------- the caliphate thought experiment ---------------- */
const pctTxt = s => s.pct == null ? 'water' : s.pct >= 99 ? 'all of it' : s.pct < 1 ? 'under 1%' : `${s.pct}%`;  /* null: a stretch of sea, not a state */
const kmTxt = n => { const p = Math.pow(10, Math.max(0, Math.floor(Math.log10(n)) - 2)); return (Math.round(n/p)*p).toLocaleString('en'); };
const listAnd = a => a.length < 3 ? a.join(' and ') : a.slice(0,-1).join(', ') + ' and ' + a[a.length-1];
/* the Muslim-majority countries of Africa added to the Greater Caliphate, with Pew's 2020 share, read from the outline data */
const AFR = CALIPH.g.afr || [];
const theN = n => /^(Gambia|Comoros)$/.test(n) ? 'the ' + n : n;
const AFR_LIST = listAnd(AFR.slice().sort((a,b)=>b.pew-a.pew).map(a=>`${theN(a.n)} (${Math.round(a.pew)}%)`));
const AFR_NAMES = listAnd(AFR.map(a=>theN(a.n)));
const JOIN_BODY = `<p><b>Lands joined to the rest.</b> The ruled parts left gaps between them, so V7 also takes in the lands that join them up, in two rounds. First the western Mediterranean: the rest of Italy (central and northern Italy, with the north of Sardinia) and all of France beyond Septimania and Fraxinetum, with Corsica, Monaco, San Marino and Andorra, so that Iberia, France, Italy, Sicily, Sardinia and Corsica form one connected territory. Then the Balkans and the Black Sea: Austria, Slovenia and the rest of Croatia and Hungary, which join Italy to the Balkans and Hungary (the Ottomans besieged Vienna in 1529 and 1683 and raided Styria and Carinthia, but never ruled Austria), and the rest of Ukraine with the Southern and North Caucasus districts of Russia (Adygea, Astrakhan, Volgograd, Kalmykia, Rostov, Dagestan, Ingushetia, Kabardino-Balkaria, Karachay-Cherkessia, North Ossetia, Stavropol and Chechnya), which join the lands north of the Black Sea to the Kuban, the Caucasus and Kazakhstan around the north of the Caspian. The Caspian is now enclosed all round.</p><p><b>What is source and what is mine.</b> No caliphate in the counted list is known to have ruled the western Mediterranean lands added here: Sicily, Bari, Taranto and Calabria and the south of Sardinia were ruled, and Corsica is on the list of lands left out of the ruled parts as unconfirmed. In France only Septimania (Narbonne, about 719/720 to 759) and Fraxinetum (about 887 to 972) were ruled. Elsewhere the Umayyad armies only campaigned or held towns briefly: they were beaten at Toulouse in 721 and between Tours and Poitiers in 732, and Avignon and Arles submitted in 734 but were taken back by Charles Martel from 737. These were raids and short occupations, not rule, so the rest of France is marked as joined. For the Balkan and Black Sea lands this was not researched further. Some of them may have been under an Ottoman or Crimean overlord at some time (my guess, from general knowledge: parts of the Ukrainian steppe, the Circassian and Kabardian lands, and the Sisak area of Croatia), but I have not checked it, so all of them stay in the joined group and out of the ruled one. The rule I used is mine, not the sources’: whole countries or whole districts, only as many as it takes for every land to touch the next by land. Switzerland, Slovakia’s west and the rest of Russia are not in; where the line stops is a choice, not a finding. These lands are marked as joined in the tables and on the map, and kept apart from the ruled lands.</p>`;
const AFR_BODY = `<p><b>The Muslim-majority countries of Africa.</b> V7 also takes in, whole, every African country not already in it where Muslims are more than half of the people in the Pew Research Center’s 2020 estimates: ${AFR_LIST}. This is a modern population test, not a historical one; the sources give these lands no status. Eritrea (52%) is already in the core. Left out: Côte d’Ivoire (46%) and Tanzania (30%), which fall below half in the same table, and Mayotte (a French department) and Zanzibar (part of Tanzania), which are not countries. Two of the eleven are close calls and are marked in the tables: Pew puts both Nigeria and Guinea-Bissau at 56%, but Nigeria has no recent official count of religion, and older estimates for Guinea-Bissau gave about 45%, and later surveys near half. Read both as “about half”. Pew’s table was read through a summary, not checked cell by cell.</p>`;
Object.assign(INFO, {
  caliph:{title:"A caliphate of the best lands", src:[], cert:"uncertain", body:`
    <p><b>A thought experiment. This is my synthesis, not a ruling.</b> No text, early scholar or geographer drew this line. It is the smallest single territory that holds every land the sources give a status: al-Ḥijāz with the two ḥarams, al-Shām with Filasṭīn and al-Aqṣā, Sinai and al-Ṭūr, al-Yaman, and the Nile valley and Delta of Miṣr. Where the sources disagree on an edge, I took the widest reading.</p>
    <p>Najd, al-ʿIrāq, the Gulf, al-Ḥabashah and Bilād al-Rūm fall outside, because no status for them is established. The result is a ring around the Red Sea and up the Levant.</p>
    <p>By my rough measurement it covers about ${(CALIPH.km2/1e6).toFixed(1)} million km² in ${CALIPH.states.length} present-day states and territories: ${CALIPH.states.map(s=>`${s.n} (${pctTxt(s)})`).join(', ')}.</p>
    <p><a href="#synth" class="tosynth">What the texts say about the caliphate, and the limits of this outline</a></p>`,
    refs:[`<a href="https://quran.com/24:55" target="_blank" rel="noopener">Qur'an 24:55</a>`, sn('tirmidhi',2226,'Al-Tirmidhī 2226'), sn('abudawud',2535,'Abū Dāwūd 2535'), `<a href="https://dorar.net/h/R7HZBi1v" target="_blank" rel="noopener">The hadith of the stages (dorar.net)</a>`, `<a href="https://en.wikipedia.org/wiki/Letter_to_Baghdadi" target="_blank" rel="noopener">Letter to Baghdadi, 2014</a>`]}
});
Object.assign(INFO, {
  histreg:{title:'Historical region names', src:['classical'], cert:'uncertain', body:`<p>The names the classical geographers used for the lands around the core: al-Andalus and the three parts of al-Maghrib, Ifrīqiyah, Barqah and Fazzān; Bilād al-Sūdān, al-Nūbah and the coast of Bilād al-Zanj; Khurāsān, Mā warāʾ al-Nahr (the land beyond the Oxus), Khwārazm, Farghānah, Sijistān, Makrān and al-Sind; Ṭabaristān, Ādharbayjān, Arrān and Armīniyah; and, further out, al-Hind, Bilād al-Turk and Bilād al-Ṣīn.</p><p>They are drawn as names only, placed approximately. I did not re-read the geographers on their limits, so no edges are drawn.</p>`},
  caliphg:{title:"V7", src:[], cert:"uncertain", body:`<p><b>The core caliphate, extended.</b> Drawn to the author’s specification as one territory in the core's colour: V5, unchanged, with the Muslim-majority countries of Africa (${AFR_NAMES}), and every land beyond them that a caliphate once ruled, only the part that was ruled, with the lands that join them up (Italy, France, Slovenia, the Balkans, Ukraine and southern Russia, below). It is not from the sources and not a ruling.</p>${AFR_BODY}<p><b>Lands once ruled by caliphates.</b> Spain, Portugal, Sicily and Malta are in the core. Beyond them: al-Andalus (Spain, Portugal and Gibraltar, 711 to the 1230s); Septimania around Narbonne (719–759) and Fraxinetum in Provence (about 887–972); Sicily (827–1091), Bari, Taranto and Calabria (840s–880s), Sardinia's south (Mujāhid of Denia’s brief occupation, 1015–16) and Malta (870–1091); Greece, with the Cretan emirate (about 827–961) and Ottoman rule (to 1830 in the south, to 1912–13 in the north); the Ottoman Balkans, Slavonia, Lika and Dalmatia, with Dubrovnik as a tributary; Ottoman Hungary (1541–1699) and southern and eastern Slovakia; Romania and Moldova as Ottoman provinces and vassals; southern Ukraine and Crimea (the Crimean Khanate, Yedisan and Podolia); the Kuban, Taman and Azov, and Derbent (Bāb al-Abwāb); the Sokoto Caliphate (1804–1903) in Nigeria, Niger, Burkina Faso, Cameroon and its fringes in Chad and the Central African Republic (Nigeria, Niger, Burkina Faso and Chad are now counted whole, above); Tibesti and Borkou (Ottoman garrisons, about 1908–1912); Equatoria in northern Uganda (Egypt under the Ottomans, 1870s–1889); the Delhi Sultanate at its height, invested by the Abbasid caliph in 1229, with Bengal; and Kashgaria in Xinjiang (the Karakhanids, who recognised the Abbasids, and an Ottoman vassal state in 1873–77). Each is labelled on the map with its caliphate and dates.</p>${JOIN_BODY}<p>The first additions follow the usual definition of the Greater Middle East, a modern geopolitical term; the historical additions come from the dynasty and province histories listed under Sources. The name is the author’s. The sources give none of these lands a sacred status; their place in Islamic history is conquest history.</p><p><a href="#regions" class="toregions">Regional index</a> · <a href="#synth" class="tosynth">the texts and the limits of these outlines</a></p>`, refs:[]},
  caliphx:{title:"The complete outline", src:[], cert:"uncertain", body:`
    %%LEAD%%
    <p><b>Not an outline of the best lands.</b> The lands the sources honour are inside the black dotted line. Everything between that line and this outline comes from the author’s specification.</p>
    <p><b>How I read the two "Greater" terms.</b> Greater Syria is taken as Syria, Lebanon, Jordan, Israel and Palestine, plus Bilād al-Shām's belt in Türkiye. "Greater Israel" is a term from Zionist maximalism and its critics, not an Islamic category; its widest reading runs from the Nile to the Euphrates. With all of Iraq and Egypt already in, neither term adds land of its own.</p>
    %%IRAQ%%
    %%SRC%%
    %%GC%%
    %%AREA%%
    <p><a href="#synth" class="tosynth">The texts, both outlines and their limits</a></p>`,
    refs:[sn('muslim',2839,'Muslim 2839'), sn('muslim','2546b','Muslim 2546'), sn('bukhari',3207,'Al-Bukhārī 3207'), sn('bukhari',3887,'Al-Bukhārī 3887'), sn('muslim',164,'Muslim 164'), sn('abudawud',4302,'Abū Dāwūd 4302'), sn('bukhari',2924,'Al-Bukhārī 2924'), sn('muslim',2897,'Muslim 2897'), sn('abudawud',2535,'Abū Dāwūd 2535'), `<a href="https://en.wikipedia.org/wiki/Letter_to_Baghdadi" target="_blank" rel="noopener">Letter to Baghdadi, 2014</a>`]}
});
/* ---------------- the versions of the user's outline ---------------- */
const CX_BODY = INFO.caliphx.body;
/* Dār al-Amān: the names chosen for the outline, and the capital */
const NAMES_P = `<p><b>Names, the author’s choice.</b> The country is <b>Dār al-Amān</b> (<span lang="ar" dir="rtl">دار الأمان</span>), “the abode of safety”; its formal title is <b>al-Khilāfa al-Amīna</b> (<span lang="ar" dir="rtl">الخلافة الأمينة</span>), “the trustworthy caliphate”; its people are <b>Amānī</b> (plural Amāniyyūn); its capital is al-Quds (Jerusalem), marked with a star. None of these names comes from the sources. In classical law <i>amān</i> is a guarantee of safety given to a person; I found no classical text that uses Dār al-Amān as the name of a state. The province names on the map, and their short tags when zoomed out (ŠM, ḤJ, YM …), are the classical region names used across this atlas.</p>`;
INFO.capital = {title:'al-Quds · capital of Dār al-Amān', src:[], cert:'uncertain', body:`<p><b>The author’s choice, not from the sources.</b> al-Quds (Bayt al-Maqdis, Jerusalem) is the capital of Dār al-Amān in this outline. The gold star and ring mark the city; al-Masjid al-Aqṣā keeps its own marker and notes.</p>
  <p><b>For comparison, where caliphs ruled from.</b> No caliphate had its capital at Jerusalem. The Prophet ﷺ and the first three caliphs ruled from Madinah, ʿAlī from Kufa, the Umayyads from Damascus, the Abbasids chiefly from Baghdad, the Fatimids from Ifrīqiya and then Cairo, the Umayyads of al-Andalus from Córdoba, the Almohads from Marrakesh, the Ottomans from Istanbul and the Sokoto Caliphate from Sokoto. Two links to the city and its province: Muʿāwiya is reported to have received the oath of allegiance as caliph at Jerusalem (Īliyāʾ) in 40/660, and the Umayyad caliph Sulaymān ruled from al-Ramla, the town he founded in Filasṭīn. These two points are from general knowledge; I have not checked them against the chronicles for this atlas.</p>${NAMES_P}`, refs:[]};
/* the parts of the outline note that differ between the three versions */
/* Version 71: the four rivers of the hadith, end to end in every version (the author's request) */
const RIVERS_P = `<p><b>The four rivers, end to end, at the author’s request.</b> Every version holds whole the four rivers that a hadith names among the rivers of Paradise: “Sayḥān, Jayḥān, the Euphrates and the Nile are all among the rivers of Paradise” (Ṣaḥīḥ Muslim 2839, from Abū Hurayrah). Sayḥān and Jayḥān are taken here as the rivers of Adana and al-Maṣṣīṣa in southern Türkiye, today’s Seyhan and Ceyhan, not the Sayḥūn and Jayḥūn of Central Asia (the Syr Darya and Amu Darya); that identification is reported from al-Nawawī’s commentary on Muslim, which I could not open to check. In the account of the Night Journey, the Nile and the Euphrates are the two outward rivers at the root of the Lote Tree of the Furthest Boundary (al-Bukhārī 3207 and 3887; Muslim 164). The hadith speaks of the rivers; it gives the lands along them no status, and taking those lands in is the author’s specification, not a ruling.</p>`;
const CX_SPEC = '<b>Drawn to the author’s specification. It is not from the sources, and not a ruling.</b>';
/* V2 (Complete; V1 before Version 66): the Complete outline of Version 47 (restored in Version 55) */
const CX_CORE = (iran, nf, nb)=> `the whole Arabian Peninsula; Greater Syria; Greater Israel in its widest reading; all of Iraq${iran ? ' and Iran, with Greater Iraq inside them' : ''}; all of Türkiye;${iran ? ' Georgia, Armenia and Azerbaijan, by their modern borders, with no Russian land (Version 151);' : ''} the whole island of Cyprus; all of Egypt, Sudan, South Sudan, Somalia (with Somaliland), Ethiopia, Eritrea and Djibouti, with Uganda, Kenya, Tanzania, Rwanda and Burundi, whole, so that the whole Nile, from its farthest headstream to the sea, and Lake Victoria lie inside, with all of Lake Albert, DR Congo’s half included (Versions 143–144); the Comoros and Mayotte; ${iran ? '' : 'and '}all of Libya, Tunisia and Greece${iran ? ', so that, with Türkiye, Cyprus, Georgia, Syria and Iraq, Greater Turkey as the Misak-ı Millî map draws it lies inside' + (nb ? '' : '; and the whole Balkan Peninsula as Wikipedia’s map draws it (Bulgaria, Bosnia and Herzegovina, Montenegro, Albania, Kosovo and North Macedonia whole, with Croatia south of the Sava and Kupa and all its islands, Serbia south of the Sava and Danube, south-western Slovenia, Romania’s Dobruja and Trieste)') : ''}${iran ? '; and all of Pakistan (with Azad Kashmir and Gilgit-Baltistan), Afghanistan and Turkmenistan, by today’s borders, with Greater Khurāsān at the widest extent any classical source or geographer gives it (since Version 139): the author’s three Khorasan maps; all of Transoxiana and Khwārazm as his maps draw them (all of Tajikistan and, since Version 141, all of Uzbekistan, with Nukus, the Ustyurt and the Farghāna valley with Osh), and Manqishlāq on the Caspian (Kazakhstan’s Mangystau region, with Aktau; Version 141); Isbījāb’s district (Shymkent, Turkistan, Otrār, Ṭarāz to Mirkī); the edge towns the geographers name, Jand and Yanghikant on the lower Syr Darya (the Qyzylorda region, with Aralsk and Baikonur) and Nawākath and Barskhān in the Chu valley and by Issyk-Kul (Bishkek, Tokmok, Karakol), with the Naryn country enclosed between them (Version 140), so that all of Kyrgyzstan is inside; and, on Lambton’s reading of “the Chinese desert and the Pamirs”, the Kashgar oasis to the Taklamakan’s edge; and, since Version 133, the India–Pakistan border as it is today' : ''}`;
/* V5 (Complete, extended; Complete V3 before Version 66): the Complete outline of Version 54; V3 (to Iraq), V6 and V7 are built on it */
const CX_CORE3 = (iran)=> `the whole Arabian Peninsula; Greater Syria; Greater Israel in its widest reading; all of Iraq${iran ? ' and Iran, with Greater Iraq inside them' : ''}; all of Türkiye;${iran ? ' Georgia, Armenia and Azerbaijan, with Derbent (Bāb al-Abwāb), the Samur valley and the Dagestan coast of the Caspian;' : ''} the whole island of Cyprus, and the island of Arwād off Ṭarṭūs (marked with a dot); all of Egypt, Sudan, South Sudan, Somalia (with Somaliland), Ethiopia, Eritrea and Djibouti, with Uganda, Kenya, Tanzania, Rwanda and Burundi, whole, so that the whole Nile, from its farthest headstream to the sea, and Lake Victoria lie inside; all of Libya, Tunisia, Algeria and Morocco, with Western Sahara (both the part Morocco holds and the rest) and Mauritania; ${iran ? '' : 'and '}all of Greece, Spain and Portugal with their islands, Sicily with its islands, and Malta${iran ? '; and all of Kazakhstan, Turkmenistan, Uzbekistan, Tajikistan, Kyrgyzstan, Afghanistan and Pakistan (with Azad Kashmir and Gilgit-Baltistan)' : ''}`;
const CX_LEAD = {
  me2: `<p>${CX_SPEC} <b>V4</b> is V1 with three more lands, each whole, at the author’s request: Tunisia, Afghanistan and Pakistan (as the base map draws it, with Azad Kashmir and Gilgit-Baltistan). Morocco, Western Sahara and Algeria, which it held until Version 111, were taken out in Version 112 at his request. V1 is the sixteen states of a Middle East reference map supplied by the author (Türkiye, Syria, Lebanon, Israel, Palestine, Jordan, Iraq, Iran, Egypt, Saudi Arabia, Kuwait, Bahrain, Qatar, the United Arab Emirates, Oman and Yemen), the whole of Libya, and the lands of the whole Nile (Sudan with Bir Tawil, South Sudan, Ethiopia, Uganda, Kenya, Tanzania, Rwanda and Burundi), with Eritrea, Somaliland and Somalia since Version 110 and Djibouti since Version 111. So V4 runs unbroken from Tunisia to the Indus, up the Nile to Lake Victoria and round the Horn of Africa, but leaves out the rest of North Africa, the Caucasus and Central Asia, which V5 takes in. Since Version 112 it is smaller than V2 and V3; the versions keep their numbers. The best-lands outline lies wholly inside it.</p>`,
  me: `<p>${CX_SPEC} <b>V1</b> is the smallest outline. It starts from the sixteen states that a Middle East reference map supplied by the author shades, each whole: Türkiye, Syria, Lebanon, Israel, Palestine, Jordan, Iraq, Iran, Egypt, Saudi Arabia, Kuwait, Bahrain, Qatar, the United Arab Emirates, Oman and Yemen (with Socotra). As on that map, Egypt is drawn with the Halaʾib triangle, which Sudan also claims, and Cyprus is left out. At the author’s request it also takes in the whole of Libya and, so that the four rivers named above lie inside end to end, the whole Nile: Sudan (with Bir Tawil), South Sudan and Ethiopia (the Blue Nile), and Uganda, Kenya, Tanzania, Rwanda and Burundi (the White Nile’s farthest sources and Lake Victoria). Since Version 110, also at the author’s request, it holds Eritrea, Somaliland and Somalia, each whole, and since Version 111 Djibouti too, so the whole Horn of Africa is inside. The best-lands outline lies wholly inside it. The larger versions are not all built on V1 (V3, for one, leaves out Iran); each is described in its own note.</p>`,
  v2: `<p>${CX_SPEC} <b>V6</b> (called Complete V2 before Version 66) is V5 with more lands added. V5 already holds every land on a Greater Middle East reference map supplied by the author (Western Sahara, Mauritania and Kazakhstan moved into V5 in Version 73). V6 takes in the islands of Corsica and Sardinia and, whole, the Muslim-majority countries of Africa not already inside: Chad, Mali, Niger, Nigeria, Burkina Faso, Guinea, Senegal, Sierra Leone, Guinea-Bissau, the Gambia and the Comoros, and, whole, Cameroon, whose north was the Sokoto Caliphate’s Adamawa emirate. In Nigeria and Guinea-Bissau Muslims are about half the population, and estimates vary. It also takes in East Turkestan (Xinjiang in China, with a strip of western Gansu), as a map the author supplied draws it; two further maps divide it into the Tarim basin and Turfan, Ürümqi and the east (the lands of Yettishar, Yaqub Beg’s state of the 1860s–1870s) and the Ili region. V5 holds the best-lands outline and adds ${CX_CORE3(true)}. How Muslim rulers held each land of the reference map, province by province, is set out below.</p>`,
  v3: `<p>${CX_SPEC} <b>V5</b> (called Complete V3 before Version 66) is the widest complete outline. It holds the best-lands outline and adds ${CX_CORE3(true)}. V3, V6 and V7 are built on it; V2 is a smaller outline that ends at Tunisia’s western border.</p>`,
  full: `<p>${CX_SPEC} <b>V2</b> (called Complete, or V1, before Version 66) holds the best-lands outline and adds ${CX_CORE(true)}. It ends at Tunisia’s western border (Tunisia was added in Version 69); V5 goes further, and V3, V6 and V7 are built on V5.</p><p><b>No gaps between lands (Version 117), at the author’s request.</b> “Fill these gaps… don’t keep such gaps in between lands, from now”: land left outside in pockets between parts of the outline is now taken in. Found by closing the outline by about 50 km (my method): in Central Asia, Kyrgyzstan’s Talas valley between Ṭarāz, Bishkek and the Farghāna crests (about 11,300 km²), Karakalpakstan west of the Amu Darya round Khiva, Khojeyli and Kungrad (about 5,400 km²), the dry bed of the Aral between the line and today’s water (about 3,500 km²), the wedges between the Syr Darya and the Karatau (about 3,300 km²) and the Tashkurgan pocket in China (about 1,600 km²), with slivers of 20 km² or less anywhere that the outline encloses (about 26,000 km² in all). Seven small settlements that the new edges cut are taken in whole; none is cut after. Places where the line only bends inward (along rivers and borders) are not counted as gaps and were put to the author.</p><p><b>Defensible frontiers in Central Asia (Version 116), at the author’s request.</b> Asked to make the borders here “politically strong”, the author chose defensible frontiers for V2, V2-B and V2N, and then the two rivers and the Chu. V2 and V2-B take V2N’s natural frontiers (the Punjab to the Beas and Sutlej, the Farghāna valley to its crests, the Turkistan region to the Karatau; about 152,000 km²), so V2 and V2N had the same outline, and in Version 118 V2N was removed. All three then go out to the two great rivers of Transoxiana, the Amu Darya (the Oxus, Jayḥūn) and the Syr Darya (the Jaxartes, Sayḥūn): the line runs down the Amu Darya to the old shore of the Aral Sea and up the Syr Darya, so all the land between them lies inside (about 155,000 km²: the Kyzylkum, Nukus and Karakalpakstan east of the Amu, and Kazakhstan’s south bank of the Syr Darya). The classical geographers left Transoxiana’s northern frontier ill-defined (Bosworth, “Mā warāʾ al-nahr”, Encyclopaedia Iranica), so the rivers as its frontier are my choice. In the east the line goes out to the Chu river and Kyrgyzstan’s border (about 66,000 km² of Kazakhstan’s Zhambyl region, with Ṭarāz and the Moyynkum sands south of the Chu). The Amu and Syr Darya are from Natural Earth, the Chu from Overture Maps, the Aral’s old shore from Natural Earth’s historic-lakes file. Still not on a barrier: the straight province lines across the sands north of the Karatau (the Chu dries out in the sands at about 45° N, south of them). Towns that the new lines cut are taken in whole, as elsewhere: 78 settlements over five passes, about 80,500 buildings that were on the outer side (Overture Maps’ building outlines); after the last pass none is cut. So Qyzylorda, Zhosaly, Baikonur (the town and about 575 km² of the land Russia leases there) and Shu, which stand on the rivers, are inside whole; Khojeyli, Kungrad and Muynak, west of the Amu, and Kazaly and Aralsk, north of the Syr, are outside.</p><p><b>Greater Turkey (Versions 96–105).</b> At the author’s request V2 holds Greater Turkey as the Misak-ı Millî map draws it (the author’s specification; since Version 105 that map alone, at his request; it is not drawn as a line of its own). The Misak-ı Millî (National Pact or National Oath) is the six decisions of the last Ottoman Parliament, which met on 28 January 1920 and published them on 12 February 1920: the lands with a Turkish majority not occupied at the Armistice of Mudros were declared the homeland of the Turkish nation, and the future of the lands with an Arab majority, of Kars, Ardahan and Batum, and of Western Thrace was left to a vote of their people (Wikipedia, “Misak-ı Millî”, the article the author sent; it rests on a single source). It is a political programme of 1920, not a religious source. The map in that article (“1914–1920”, a conceptual map) draws the unoccupied core (today’s Türkiye), and numbers seven more lands: 1 Western Thrace, 2 the Dodecanese, 3 Kars, Ardahan and Batumi, 4 the Aleppo vilayet, 5 the Mosul vilayet, 6 the Zor sanjak and 7 Cyprus. All of them lie inside V2: Türkiye, Greece (with Western Thrace and the Dodecanese, and Kastellorizo, which the base map does not draw and which was traced and added in Version 100), Cyprus, Georgia (with Batumi), Syria and Iraq are whole in it. Earlier maps the author sent (a Turkish flag painted over an old map, and two others) also took in Bulgaria and a sliver of North Macedonia by Dojran (Versions 97 and 102); since Version 105 they are out of Greater Turkey, because the Misak-ı Millî map does not include them; Bulgaria and North Macedonia are back, whole, since Version 107, as part of the Balkan Peninsula (below). The Ottoman Balkans added in Version 96, and Romania, Serbia, Kosovo, North Macedonia and Crimea added in Version 103, were taken out again in Versions 97 and 104 at the author’s request.</p><p><b>The Balkan Peninsula (Version 107), at the author’s request.</b> V2 holds the whole Balkan Peninsula as the map in Wikipedia’s article “Balkans” draws it (the author’s specification): the outline is OpenStreetMap’s “Balkans” peninsula (relation 4016746, about 476,000 km²), read from Overture Maps. Its northern edge runs from the Gulf of Trieste along the Sava (through Zagreb and Belgrade) and the Danube to the Black Sea; Wikipedia: “Its northern boundary … is often given as the Danube, Sava and Kupa Rivers.” Inside it, whole: Bulgaria, Bosnia and Herzegovina, Montenegro, Albania, Kosovo and North Macedonia; in part: Croatia south of the Sava and Kupa, with Istria, Dalmatia and every Adriatic island (about 57% of Croatia), Serbia south of the Sava and Danube (about 71%), the south-west of Slovenia with its coast (about 26%), Romania’s Dobruja between the Danube and the Black Sea, and Trieste in Italy (Greece and East Thrace were in already); about 348,000 km² added. The outline’s line runs through Zagreb, Belgrade and other towns; as for the author’s other lines, each town it cuts is taken in whole (see “Towns and villages on the line”). The Ottoman Balkans added in Version 96 were a different, wider choice (with Romania, Moldova and Crimea) and are not back.</p><p><b>The Caucasus and the Caspian follow their natural border (Version 109), at the author’s request.</b> In the Caucasus the outline goes out to the crest of the Greater Caucasus, the watershed between the Black Sea and Kura side and the Kuban, Terek and Dagestan side, found on elevation data (the Mapzen terrain tiles; my method). Added: Russia’s Black Sea coast between the sea and the crest, from Anapa through Novorossiysk, Gelendzhik and Tuapse to Sochi and Krasnaya Polyana (about 7,100 km²), and thin strips along the range where the border runs just north of the crest (about 600 km²). Georgia and Azerbaijan stay whole, although their northern edges (Kazbegi and Tusheti, Quba and Khachmaz) lie beyond the crest (the author’s choice: out to the crest, keep the rest). Towns the new line cut (Anapa, Adler–Veseloye by the Psou and a few hamlets, found from Overture Maps building outlines, since Meta’s population layer does not cover Russia) are taken in whole. On the Caspian the outline now follows the shore: the sea water it held (about 5,100 km²: the strip along the Turkmen coast and Gorgan Bay that the Khurāsān map drew over the water, the Anzali lagoon and thin slivers along the coast) is out.</p><p><b>The Caucasus as in V5 (Version 115), at the author’s request.</b> After the crest of Version 109, the author asked for the whole Greater Caucasus (Version 114: the Russian side down to the northern foot of the mountains, with Dagestan’s Caspian coast; under the town rule this took in Maykop, Cherkessk and Mineralnye Vody whole), and then for V5’s border instead, keeping Russia’s Black Sea coast. Russia’s part is now V5’s Dagestan block, Derbent (Bāb al-Abwāb), the Samur valley and the Dagestan coast up to 44° N (about 25,800 km², with Makhachkala, Kaspiysk, Kizilyurt, Buynaksk, Izberbash and Derbent), and the Black Sea coast from Anapa to Sochi of Version 109 (about 7,200 km²). The northern side of the range (Elbrus, Nalchik, Vladikavkaz, Grozny, Maykop) and Version 109’s thin strips along the crest are out: between the two pieces the line is Georgia’s and Azerbaijan’s border with Russia, as in V5. Towns that V5’s line in Dagestan cut are taken in whole, as elsewhere: 54 settlements over six passes (villages by Khasavyurt, Kizlyar and in the hills west of Buynaksk, and the northern edge of Anapa), about 8,500 buildings that were on the outer side; after the last pass none is cut. So V2’s line in Dagestan now runs a little outside V5’s.</p><p><b>The line along district borders (Version 125), at the author’s request.</b> “The straight line doesn’t look good. Rather, it should have the shape of the borders of Georgia and Armenia.” So the straight line of Version 124 now follows real district borders, as the borders of Georgia and Armenia do: of the 23 districts it crossed, each with half or more of its land south of the straight line is taken in whole, and each with less is left out whole (district borders from Overture Maps’ division areas). In: Novorossiysk, Abinsky, Seversky, Belorechensky, Koshekhablsky and Adygeysk on the Kuban side, Kochubeyevsky and Andropovsky in Stavropol, Nogaysky and Tarumovsky in Dagestan. Out: Anapa’s okrug, Krymsky, Takhtamukaysky, Teuchezhsky, Giaginsky (half on each side, a hair under), Kurganinsky, Novokubansky, Armavir, Uspensky, Alexandrovsky (just under half), Novoselitsky, Budyonnovsky and Neftekumsk (just under half). Maykop, Cherkessk, Pyatigorsk, Nalchik, Vladikavkaz, Grozny, Kizlyar and Elbrus are inside; Krasnodar, Armavir, Stavropol and Budyonnovsk outside. The district borders are modern ones; the choice of line is the author’s specification. Towns that the new line cut are taken in whole, as elsewhere: 33 settlements over three passes (the largest Afipsky, south-west of Krasnodar), about 1,700 buildings that were on the outer side; after the last pass none is cut. The bends where a district was left out are the line’s shape, not gaps.</p><p><b>Greater Georgia in V2 (Version 152), at the author’s request.</b> “Include greater Georgia in v2 and not in v2b.” Greater Georgia at its widest is the kingdom under Queen Tamar, which the medieval Georgian chronicles describe as reaching “from Nikopsia to Darband” (not checked against the source here). The lands it adds beyond modern Georgia (Tao-Klarjeti and Lazona in Türkiye, Saingilo in Azerbaijan and Lori in Armenia were already inside) are all in today’s Russia, and they are added to V2 only, as an exception to the modern Georgia and Azerbaijan borders: the Black Sea coast south of the main crest from Abkhazia to Nikopsia (Novomikhaylovsky; Sochi, Tuapse), Alania (North Ossetia, with Vladikavkaz), and Darband (Derbent with V5’s Dagestan block); Makhachkala, Kaspiysk, Izberbash and Novomikhaylovsky, which the new edges cut, are taken whole. About 38,500 km² in all. V2-B keeps the modern borders.</p><p><b>Back to the modern borders of Georgia and Azerbaijan (Version 151), at the author’s request.</b> “Return to modern Azerbaijan and Georgia borders.” All Russian land in the Caucasus is out of V2 and V2-B: the North Caucasus of Versions 146–150 and also V5’s Dagestan block with Derbent (Bāb al-Abwāb), which had been inside since Version 115. The border in the Caucasus is now the modern northern border of Georgia and Azerbaijan; Georgia, Armenia and Azerbaijan stay whole.</p><p><b>The orange shape copied, and Lake Albert’s border (Version 150), at the author’s request.</b> He sent his Caucasus map again beside a screenshot of Version 149: that border still had a dip in the middle and rose towards the Caspian, because the sketch had been stretched to fit real places. Now the orange edge’s own shape is copied without distortion (moved, turned and scaled only), its two ends pinned to the Kerch Strait at Taman and to the Caspian shore: from the strait it runs east, slopes down through the middle and runs flat into the Caspian, as on his map (his map is not drawn to scale, so the ends are where the line must meet the real seas; my method). At Lake Albert he drew a smooth line a little inland of the DR Congo shore, “Lake Albert draw a border professionally”: the border now follows it, with the strip of land between it and the lake (about 2,150 km²) inside, and no city or town is cut. Stray specks left off the Mozambique coast by the withdrawn extension were cleared.</p><p><b>The Caucasus exactly as the author’s map (Version 149).</b> Shown the Kuban–Kuma border of Version 148, he wrote: “This is bad. I asked for this exact one.” The North Caucasus edge is back to the top edge of the orange shading on his map, as fitted to the real borders and coasts in Version 147, and smoothed so that it is the same gentle line as on his map, from the Kerch Strait to the Caspian shore; no town bumps are added along it, so the shape stays exact. Crimea stays out. East Africa stays as in Version 148 (all of Lake Albert; the extensions withdrawn).</p><p><b>Natural borders, and the African extensions withdrawn (Version 148), at the author’s request.</b> “Make newly drawn border look nice. And implement natural border rule since changes we started making since lake Albert.” Asked how, he chose the natural features closest to his hand-drawn lines. <i>The Caucasus:</i> his orange edge runs between two rivers, so the border is now the Kuban from its mouth at Temryuk up past Krasnodar, Armavir and Nevinnomyssk to near Karachayevsk, a short link of about 20 km to the source of the Kuma, and the Kuma down past Mineralnye Vody and Budyonnovsk to the Caspian lowland (OpenStreetMap via Overture Maps): about 12,000 km² gained along the Kuma and about 15,000 km² of the Kuban lowland north of the river given up; cities and towns the rivers cut are taken whole. <i>East Africa:</i> he then asked to forget the extensions made since Lake Albert and keep Lake Albert entirely inside, so the additions of Versions 146 and 147 west and south of the great lakes (eastern DR Congo, north-eastern Zambia, Malawi, northern Mozambique) are withdrawn; V2 and V2-B hold East Africa as in Version 145, with all of Lake Albert. The Comoros and Mayotte (Version 147) stay.</p><p><b>To the Zambezi, the Comoros and the Caucasus as drawn (Version 147), at the author’s request.</b> <i>The Caucasus:</i> “I want the orange border to look exactly like this!” His sketch was fitted again, this time by matching all its drawn borders and coasts to the real ones at once (my method); its orange edge lies some 10–60 km north of Version 146’s line, so about 23,000 km² more of Russia is inside (the Kuban round Krasnodar and Armavir, more of Stavropol, the land to the Kizlyar Bay). Crimea stays out (the city of Kerch, which the town rule first caught at the strait, was taken out again). <i>The Comoros and Mayotte:</i> from a Google Maps screenshot, “add the ones in the image”: Grande Comore, Mohéli, Anjouan and Mayotte, whole (about 2,070 km²). <i>Africa:</i> “And with that extend”, then “Update” with a redrawn line: from west of Lake Tanganyika south-east through Zambia, Malawi and Mozambique to the sea just north-east of the Zambezi mouth; all land and lake east of it is inside, about 510,000 km² (northern Mozambique about 352,000 with Nampula, Pemba, Nacala, Lichinga, Cuamba, Gurúè and Mocuba; north-eastern Zambia about 71,000 with Kasama; Malawi about 84,000, the north with Mzuzu and the lake shore down to Mangochi and Zomba; a strip of DR Congo). Just west of the line, and so outside, lie Lilongwe, Blantyre, Chipata, Mpika, Tete and Quelimane. The cities and towns the new lines cut were taken whole (recognized places only, at his earlier request), among them Ilha de Moçambique, Pemba, Mocímboa da Praia, Nacala-a-Velha, Pebane and Zomba (Zomba by a small circle, having no outline in the data), and Medvyodovskaya and Voronezhskaya in the Kuban.</p><p><b>East Africa and the Caucasus expanded (Version 146), at the author’s request.</b> With two maps he asked: “Expand.” <i>Africa:</i> on a screenshot of V2 he drew a line west of the great lakes, from north of Lake Albert through eastern DR Congo and across north-eastern Zambia to the north end of Lake Malawi; all land between it and V2 is now inside V2 and V2-B, about 188,000 km² (DR Congo about 148,000, with Bunia, Goma, Bukavu, Uvira and Kalemie; Zambia about 37,000; the far north of Malawi about 2,600; about 18,700 km² of it lake water). The line was placed by fitting his screenshot’s lakes to the map (my method). <i>The Caucasus:</i> on a map shading the Caucasus from the Taman peninsula to the Caspian he asked for the same; all of Russia south of the shading’s top edge is now inside (about 117,000 km² new: the south of Krasnodar Krai with Taman, Anapa, Novorossiysk and Sochi, Adygea, Karachay-Cherkessia, Kabardino-Balkaria, North Ossetia, Ingushetia, Chechnya, southern Stavropol and all of Dagestan; Crimea stays out). His map is a drawn sketch: it was fitted on the Taman tip, the Georgia–Turkey coast, the Absheron tip and Astara, and its east end, which touches the Caspian, was stretched to the real shore, so the line may stray by some tens of kilometres (my method). Georgia, Armenia and Azerbaijan were already whole. This replaces V5’s Dagestan block of Version 127. At his request (“take cities which are recognized on Google Maps and Apple Maps… finding every single little settlement will take a lot of time”), the cities and towns the new lines cut are taken whole by their outlines (Overture Maps, class city or town; villages left as they fall): Armavir, Nevinnomyssk, Kaspiysk, Georgievsk, Mineralnye Vody, Taman, Petrovskaya, Poltavskaya, Starokorsunskaya and Tarumovka; the African line cuts none. The edges were then made to hold everything in, as in Version 145.</p><p><b>Everything in (Version 145), at the author’s request.</b> “I said I want everything in!!!” The outlines are stored on a grid of a thousandth of a degree (about 110 m), so where they followed a coast or a border exactly, hairline slivers of the lands they hold were left outside: about 420 km² in all in V2, in thousands of pieces along every coast and border (the largest in Greece, Tanzania, Pakistan and Türkiye). Each sliver is now closed by pushing the outline just past the coast or border (about 110 m, a little more in a few narrow places), so every land V2 and V2-B hold, each country listed whole, the partial lands and all that Version 144 held, lies wholly inside (0 m² outside; my method). Where that push crossed a border onto land outside, the towns and villages it cut were taken in whole, at the author’s suggestion by their named outlines (Overture Maps from OpenStreetMap, places up to 100 km², counted as cut with 5% or more on each side): 102 in V2 and 80 in V2-B, for example Aïn El Assel and Souarekh in Algeria on the Tunisian border and villages such as Endirey in Dagestan in both, and in V2 alone (which holds the Balkans) Slavonski Brod, Županja and Jasenovac on the Sava in Croatia and Jamena in Serbia. The pockets these edges closed in, the largest about 210 km² in the Kashgar–Yarkand country, were filled as gaps. In all about 6,700 km² was added to V2 (about 7,100 to V2-B).</p><p><b>The last of Lake Albert (Version 144), at the author’s request.</b> Asked whether 0.03% of the lake had been left out: it had, about 1.4 km² in 22 hairline slivers (at most about 45 m wide) along the DR Congo shore, because the outlines are stored to a thousandth of a degree (about 110 m) and cannot follow every bend of the shore. The edge now runs about 200 m inland of the DR Congo shore, so none of the lake is outside V2 or V2-B; every lakeside settlement this edge would have cut is taken in whole (Overture building footprints; about 65 settlements over several passes; my method). About 50 km² of shore land is added in all.</p><p><b>All of Lake Albert (Version 143), at the author’s request.</b> Asked whether the Nile, the Blue Nile and the White Nile lie inside end to end, I checked every stretch against V2 and V2-B (Natural Earth rivers; my method): the Kagera from its farthest springs in Burundi and Rwanda, Lake Victoria, the Victoria Nile, the Albert Nile, the Mountain Nile, the White Nile, the Blue Nile from its spring and Lake Tana, and the Nile from Khartoum through Lake Nasser to the Rosetta and Damietta mouths are all inside both. Only the western half of Lake Albert, which belongs to DR Congo, was outside (the Nile itself only crosses the lake’s northern tip, in Uganda). At his word (“sure”) that half, about 1,880 km² of water, is now inside V2 and V2-B, so the whole lake is in. The new edge is the lake’s own shore and cuts no settlement.</p><p><b>The pocket north of the Ustyurt filled (Version 142), at the author’s request.</b> On a screenshot of V2 he asked: “Fill this small pocket.” Between the Mangystau region and the Aral district a bay of Kazakhstan (the southern Baiganin and Shalkar districts, open only to the north) was left outside; it is now inside V2 and V2-B, closed by a straight edge from Mangystau’s north-east corner to the Aral district (about 20,800 km²). The new edge cuts no settlement.</p><p><b>Manqishlāq and the Ustyurt (Version 141), at the author’s request.</b> Checked against every place the classical sources name in Greater Khurāsān at its widest (from Rayy, Dāmghān and Gurgān to Sīstān, Ghazna and Badakhshān, Khwārazm, Transoxiana and Farghāna, Isbījāb, Ṭarāz and Mirkī, Jand and Yanghikant, Nawākath, Balāsāghūn and Barskhān, and Kashgar), V2 held them all; only two doubtful desert edges were outside: Manqishlāq, the peninsula Ibn Ḥawqal calls Siyāh-Kūh, a Ghuzz pasture beside Khwārazm, and the Ustyurt plateau, the Ghuzz desert between Khwārazm and the Caspian. Asked whether to add them, he said “Sure”. Both are now inside V2 and V2-B: Kazakhstan’s whole Mangystau region (Aktau, Zhanaozen, Beyneu, the Kazakh Ustyurt) and the rest of Uzbekistan, so Uzbekistan is whole (about 236,000 km² more). Neither is clearly Khurāsān in the sources; they are in so that nothing is left out (the author’s specification). One village on the new edge was taken in whole.</p><p><b>The Naryn gap filled (Version 140), at the author’s request.</b> On a screenshot of V2 he asked: “Why is there a gap here?” Version 139 had joined Farghāna, the Chu valley with Issyk-Kul, and Kashgar round the Naryn country of Kyrgyzstan without taking it in, leaving a hole of about 28,000 km² (Naryn and At-Bashy) fully enclosed by land inside. The gap check looked only at pockets on the outline’s outer edge, so it missed a hole in the middle; it now looks at enclosed holes too (any hole that is mostly land is filled). This was the only one. All of Kyrgyzstan is now inside V2 and V2-B.</p><p><b>Greater Khurāsān by all the classical sources, at its widest (Version 139), at the author’s request.</b> “Just include greater khorasan according to all classical sources and geographers to widest and maximum.” Asked, he chose to cut Central Asia back to that, and to include the edge towns the geographers name. So in Kazakhstan, Uzbekistan, Kyrgyzstan, Tajikistan and China, V2 and V2-B now hold: Khurāsān with Transoxiana and Khwārazm as in Version 135 (his three Khorasan maps, the dashed-outline and red-line maps, and Isbījāb’s district after Le Strange: Sayrām, Shymkent, Otrār, Yasī, Ṣabrān, Ṭarāz, Mirkī), since al-Yaʿqūbī stretches Khurāsān from Rayy to Farghāna, Qudāma counts Samarqand, Shāsh, Farghāna, Usrūshana, Khwārazm and Isbījāb among its cities and al-Balādhurī counts Khwārazm and Transoxiana; the Oghuz towns of the lower Syr Darya that Le Strange lists, Jand and Yanghikant (the whole Qyzylorda region, with Aralsk and Baikonur); the Turkish towns at the edge of Mā warāʾ al-Nahr that Muqaddasī and Ibn Ḥawqal name, Nawākath in the Chu valley and Barskhān by Lake Issyk-Kul (Kyrgyzstan’s Chuy and Issyk-Kul regions with Bishkek, Tokmok and Karakol); and, on the widest reading of Lambton’s “the Chinese desert and the Pamirs”, the Kashgar oasis (Version 138). Pakistan, Afghanistan and Turkmenistan stay whole. Out again (about 2.4 million km²): northern and western Kazakhstan (Astana, Aktobe, Atyrau, Aktau and the Mangystau coast) and the Balkhash country with Almaty, which no classical source counts in Khurāsān. Pockets left between lands inside were filled as gaps (about 19,800 km², most in Kyrgyzstan’s Naryn region between Farghāna, the Chu valley and Kashgar, and by the old Aral); one village on the new edge was taken in whole. The edge towns were not under Muslim rule when the geographers wrote; the district choices are mine; the whole is the author’s specification.</p><p><b>Seven countries whole, the Kashgar oasis and the last of the shore (Version 138), at the author’s request.</b> “Add entire modern Pakistan, Afghanistan, Uzbekistan, Kazakhstan, Turkmenistan, Tajikistan, Kyrgyzstan to v2 and v2b and even at the thing that you said was left outside.” All seven are now inside V2 and V2-B whole by today’s borders, Kazakhstan with Baikonur (northern and western Kazakhstan with Astana, Pavlodar, Oskemen, Kostanay, Aktobe, Uralsk, Atyrau and Aktau; the rest of Kyrgyzstan with Karakol and Naryn). The things said to be left outside are in too: the Kashgar oasis, which the widest reading of Ann Lambton’s Khurāsān could take in (“its Central Asian boundary was the Chinese desert and the Pamirs”), taken as China’s Kashgar and Kizilsu prefectures (Kashgar, Yarkand, Artux, Tashkurgan, to the Taklamakan’s western edge; about 180,000 km²; my reading of her words, and Kashgar was a Qarakhanid, not a Khurāsānī, city), and the last few km² of his region maps on the south-east Caspian shore, now taken with a few hundred metres of shore. About 2.1 million km² more in all. The new edge follows international borders and, in China, the prefectures’ borders, which cut no settlement; pockets by Aksu and the Karakoram were filled as gaps (about 6,100 km²). India’s border stays (Version 133).</p><p><b>Every last sliver (Version 137), at the author’s request.</b> Measured against each of his maps of Khurāsān, Khwārazm, Transoxiana and Mā warāʾ al-Nahr, V2 and V2-B held all of them but about 36 km² of hair-thin slivers along their edges; he wrote “Fill everything”. The slivers were widened by about 300 m within the land, so the outline can hold them, and added to both (about 650 km² with the widening); towns the slightly moved edge cut were taken in whole (8 settlements). What remains outside, about 4.6 km², lies along the south-east Caspian shore by the Gorgān bay, where the base map’s coastline and the outline’s sea edge (Version 109) differ by a few hundred metres; sea water stays out.</p><p><b>Nothing left out, in V2 and V2-B (Version 136), at the author’s request.</b> “Add it in v2b as well”, and then: “Don’t leave anything out… widest and max!!!” So the three things Version 135 had kept out are in too: Jand and Yanghikant, the Oghuz towns of the lower Syr Darya that Le Strange lists with Isbījāb’s district (taken as the whole Qyzylorda region, with Qyzylorda, Kazaly, Aralsk and Baikonur), and the Transoxiana of the author’s green locator map, the Balkhash country (Semirechye) with Almaty, Taldykorgan, Balkhash and Karaganda, and northern Kyrgyzstan with Bishkek. The Balkhash country is Transoxiana only in the loosest modern sense and was never counted in Khurāsān by the classical geographers; it is here because the author asked for everything (his specification). About 727,000 km² more in V2; V2-B now has exactly V2’s Central Asia (about 1.1 million km² more than in Version 135). Towns that the new edge cut are taken in whole, as elsewhere: 43 settlements over four passes, about 4,000 buildings that were on the outer side; pockets left between lands inside were filled as gaps (about 6,800 km², the largest by the old Aral west of the Amu delta and in Kyrgyzstan’s Naryn region). Sea water stays out (Version 109) and India’s border stays (Version 133).</p><p><b>Greater Khurāsān at its widest and fullest, in V2 only (Version 135), at the author’s request.</b> On the table of Version 134 he ticked “Wide sense of al-Yaʿqūbī and Lambton” and wrote: “Add this in v2 and not v2b and make sure you get the widest and max greater khorasan.” So V2 (not V2-B, which keeps Version 134’s Khurāsān) now holds Khurāsān in the widest sense the sources give: his three Khorasan maps with all of Transoxiana and Khwārazm as his maps draw them (the dashed-outline map and the red-line map of Mā warāʾ al-Nahr), every province of Uzbekistan, Tajikistan, Kyrgyzstan and Kazakhstan those maps cover to 99% or more taken whole, and Isbījāb’s district, since Qudāma counts Isbījāb among Khurāsān’s cities: as Le Strange lists it (Sayrām, Chimkand, Fārāb/Otrār, Yasī, Ṣabrān, Ṭarāz and Mirkī), on today’s map the Turkistan region with Shymkent and, from the Zhambyl region, the Ṭarāz oasis to Merke (my mapping of his list to districts; Jand and Yanghikant, Oghuz towns not under Muslim rule, are left out, as is the Balkhash country of the author’s locator map, which is not Khurāsān in any classical sense). Pockets left between lands inside were filled as gaps (about 29,000 km², the largest the Talas valley of Kyrgyzstan between Ṭarāz and Farghāna, and the edges of the Sarysu and Karatau country). About 368,000 km² more in all, with Nukus, Shymkent, Turkistan, Otrār, Ṭarāz and Talas. Towns that the new edge cut are taken in whole, as elsewhere: 24 settlements over seven passes, about 1,400 buildings that were on the outer side. Khurāsān in this sense is a classical name for the lands governed from Khurāsān, not a single classical border; the outline is the author’s specification.</p><p><b>The last slivers of Greater Khurāsān (Version 134), at the author’s request.</b> Asked whether all of Greater Khurāsān was inside V2, the measure showed his three Khorasan maps inside but for about 16 km² of hair-thin slivers along their edges, too thin for the outline’s precision (about 100 m). He wrote: “Take everything of what’s outside, inside.” The slivers were widened by a few hundred metres within the land so they hold, and added to V2 and V2-B (about 165 km² with the widening); about 4 km² along the south-east Caspian shore stays out, where the base map’s coastline and V2’s shoreline differ by a few hundred metres. Sea water stays out (Version 109).</p><p><b>The political border with India (Version 133), at the author’s request.</b> “Maintain political border with India.” India’s land that V2 and V2-B held since the natural frontiers of Version 92 (the Punjab to the Beas and Sutlej: Amritsar, Tarn Taran, Gurdaspur, with Pathankot and Kathua, about 8,900 km²) is out again, so the outline follows today’s India–Pakistan border as the base map draws it (Azad Kashmir and Gilgit-Baltistan, on Pakistan’s side, stay).</p><p><b>Only Greater Khurāsān in Central Asia (Version 132), at the author’s request.</b> After Version 131 he wrote “Ykw remove everything except greater khorasan”; asked, he chose Greater Khurāsān at its widest (the union of his three Khorasan maps, as in Version 87, about 1.88 million km²) and to keep Turkmenistan, Afghanistan and Pakistan whole. So in Kazakhstan, Uzbekistan, Kyrgyzstan, Tajikistan and China, V2 and V2-B now hold Greater Khurāsān alone, with every province those maps cover to 99% or more taken whole (Tajikistan is thus whole): all of Tajikistan, most of Uzbekistan with Bukhārā, Samarqand, Tashkent, Khiva and the Farghāna valley, southern Kyrgyzstan with Osh, a strip of Kazakhstan by Tashkent and a thin edge of China. Out again (about 1.39 million km²): Transoxiana and Khwārazm beyond Khurāsān, the north of Uzbekistan and Karakalpakstan (Nukus, the Ustyurt), all the Kazakh lands of Versions 116–131 (the Syr Darya, Shymkent, Turkistan, Ṭarāz, Qyzylorda, Mangystau with Aktau, and the land round Lake Balkhash with Almaty) and northern Kyrgyzstan with Bishkek. India’s Punjab to the Beas and Sutlej, outside Central Asia, stays. Towns that the Khurāsān edge cuts are taken in whole, as elsewhere: 142 settlements over eight passes (among them Osh and towns by Namangan and Tashkent), about 79,000 buildings that were on the outer side; pockets the edge left between lands inside were filled as gaps (about 9,900 km², among them the Chatkal valley).</p><p><b>Every traced map of Khurāsān, Khwārazm and Transoxiana whole (Version 131), at the author’s request.</b> He asked whether the whole of Greater Khurāsān, Khwārazm and Transoxiana was inside V2; measured against every map of them he had given (the Wikipedia Greater Khorasan map, his Khorasan map, the dashed-outline map of Khurāsān, Khwārazm and Transoxiana, the red-line map of Mā warāʾ al-Nahr and the green locator map of Transoxiana), all of Khurāsān, Khwārazm and the dashed Transoxiana were inside, but about 10,200 km² of the red-line map (the mountains east of Farghāna, in Kyrgyzstan and China) and about 551,000 km² of the locator map (south-east Kazakhstan round Lake Balkhash and northern Kyrgyzstan, left out since the Chu frontier of Version 116) were not. He answered: “Add all the land that’s missing… no exceptions.” All of that land is now inside V2 and V2-B (about 560,000 km², with Almaty, Bishkek, Taldykorgan, Balkhash and Karaganda); the Chu frontier no longer bounds it there. Sea water stays out, as everywhere since Version 109. The edge is his maps’ edge; towns that it cut are taken in whole, as elsewhere: 45 settlements over four passes (among them Kochkor in Kyrgyzstan and villages by Karaganda and in the Ili valley), about 4,100 buildings that were on the outer side. Three pockets along the new edge were filled as gaps (about 3,500 km²). The regions’ limits are the author’s maps, not a classical definition; classical geographers drew them in different ways.</p><p><b>A new border across Kazakhstan (Version 130), at the author’s request.</b> On a screenshot of V2 he drew a black line across the land added in Versions 127–129, from the Caspian’s bay north of the Buzachi peninsula to the outline east of the Aral; asked what it meant, he chose “Make it the new border”. The line was placed from the screenshot’s grid (about 53.1° E 45.6° N, 55.1° E 46.5° N, 58.0° E 47.2° N, 60.4° E 47.25° N, 63.0° E 47.2° N), and everything north of it is out of V2 and V2-B again (about 116,500 km²): Atyrau and the land along the Caspian’s north-east shore, most of the Zhylyoi district (Kulsary), Makat, the northern Baiganin and Shalkar districts (with the town of Shalkar) and the north of the Aral district. South of it everything stays: the Mangystau region with the Buzachi peninsula, Beyneu, the Ustyurt, Aralsk and the Small Aral. The border is the author’s line, not a district border. One village by the line east of the Aral was taken in whole, as elsewhere.</p><p><b>On to Atyrau (Version 129), at the author’s request.</b> On the close-up picture of Version 128 he drew a red line from the Caspian coast at Atyrau to the north-west corner of the Shalkar district, the same request as before: fill what lies south of it. His line was placed from the picture’s own projection (checked on Baku and on the Shalkar district’s northern tip): about 51.8° E 47.2° N at Atyrau, 54.4° E 47.7° N, 56.5° E 47.8° N, 58.8° E 48.1° N. As in Version 128, each district with half or more of its land south of the line is inside whole: Atyrau city with its okrug (74%), Zhylyoi (98%, with Kulsary and the Tengiz field), Makat (70%) and Baiganin (72%); the slivers of the Kyzylkoga and Mugalzhar districts under the line are inside up to the line. About 76,600 km² more. Towns that the new line cut are taken in whole, as elsewhere: 13 small settlements over two passes (by Atyrau and along the line), about 200 buildings that were on the outer side.</p><p><b>The notch north of Beyneu filled (Version 128), at the author’s request.</b> On a screenshot of V2 he drew a line over the notch that Version 127 left between the Beyneu and Aral districts (Shalkar, Baiganin and Zhylyoi districts out) and wrote “Fill this region”. His line was placed on the map from the screenshot’s grid (about 54.2° E 46.2° N, 58.1° E 47.4° N, 61.8° E 47.8° N, the Aral district’s northern tip). The Shalkar district has 56% of its land south of it, so it is inside whole (the rule of Version 125), with the town of Shalkar; the rest of the region under his line, parts of the Baiganin and Zhylyoi districts, is inside exactly up to his line, since he asked for all of it. About 83,600 km² more; the new line cuts no settlement.</p><p><b>Connected to the Caspian, and the Caucasus as in V5 again (Version 127), at the author’s request.</b> On a screenshot of V2-B he drew a line from the north-east corner of the Caspian to the outline’s corner in Kazakhstan north of the Syr Darya and wrote “Connect this”; then, with a screenshot of V5’s Caucasus, “make the current one go back to the one in v5”. Kazakhstan: his line was placed on the map from the outline’s corners (it runs about 52.5° E 46° N, 57.3° E 46.9° N, 61.8° E 47.5° N, 66.7° E 45.7° N) and, as in Version 125, taken by whole districts: each with half or more of its land south of the line is inside whole. In: the whole Mangystau region (Aktau, Zhanaozen, the Tupkaragan peninsula, Munaily, Mangystau, Karakiya and Beyneu districts, with the Kazakh Ustyurt) and, in the Qyzylorda region, the Aral, Kazaly, Karmakshy, Zhalagash, Syrdariya and Shiyeli districts and Qyzylorda city, with Aralsk, Baikonur and the Small Aral. Out: Shalkar (46% south of the line, just under half), Baiganin (32%) and Zhylyoi (20%) in the Aktobe and Atyrau regions, and Irgiz and Ulytau. About 283,000 km² more; the new line cuts no settlement; a pocket by the Small Aral (about 5,900 km²) was filled as a gap. The Caucasus: Russia’s land in V2 and V2-B is again exactly V5’s, Georgia’s and Azerbaijan’s borders with V5’s Dagestan block (about 25,800 km²), so the Black Sea coast (Version 115), the district line (Version 125) and the Taman peninsula (Version 126) are out again. Towns that V5’s line cuts are taken in whole, as elsewhere: 47 settlements over six passes (along the Dagestan block), about 7,200 buildings that were on the outer side.</p><p><b>The Taman peninsula and all of Uzbekistan (Version 126), at the author’s request.</b> On a screenshot of V2 he circled the land west of the line, the Taman peninsula, Anapa and the lower Kuban, and wrote: “It should cover this land and add entire modern Uzbekistan.” His circle was placed on the map from the outline’s corners and, as in Version 125, taken by whole districts: Anapa, Krymsky and Temryuksky (the Taman peninsula), all inside it, and Slavyansky (about half inside) and Krasnoarmeysky (about a quarter inside), taken whole because part of each lay in the circle; Krasnodar city, which the end of the circle only grazed, stays out (my reading of the drawing). Crimea and the Kerch peninsula lie outside the circle. About 8,100 km² more. The new line cut two settlements at the edge of Krasnodar’s okrug, taken in whole as elsewhere (one of them a large village, about 5,000 buildings). Uzbekistan is now inside whole by today’s borders: the Ustyurt plateau of Karakalpakstan west of the Aral, the north of the Kyzylkum and the old Aral bed on Uzbekistan’s side (about 109,000 km² more).</p><p><b>A straight line across the North Caucasus (Version 124), at the author’s request.</b> On two screenshots of his map he circled the inlet of the Caspian coast just north of V5’s Dagestan block (the Kizlyar Bay) and the tip of the Black Sea strip at Anapa, and asked for a line from one to the other with everything south of it filled. That straight line was replaced by district borders in Version 125.</p><p><b>Towns and villages on the line (Version 106), at the author’s request.</b> No town, village or neighbourhood is cut by V2’s own lines any more. Where the author’s line ran through a settlement, it now goes round it and the whole settlement is inside: 230 settlements it cut (among them Belgrade and Zagreb on the Balkan line, Pathankot and Kathua in India, the Turtkul–Beruniy oasis, Shovot and Burlak in Uzbekistan, and villages in Kyrgyzstan and Kazakhstan), with about 1.73 million people who were on the outer side, and 40 neighbouring villages that the redrawn line touched (about 30,000 people); about 1,100 km² in all. In China the line crosses no settlement. Found with Meta’s High Resolution Settlement Layer (people per ~30 m cell; houses less than ~90 m apart counted as one settlement) and Overture Maps for real borders and names (my method; the people are grid estimates, not a census). Where V2 follows an existing international border it divides no one newly; 175 places have grown together across those borders (for example Goma and Gisenyi, Bukavu and Rusizi, Tunduma and Nakonde, and Mahagi and Aru on the Congo–Uganda border). They are listed in the project’s report (reports/settlements_on_the_line.md) but not changed, because their other halves lie in countries outside V2.</p><p><b>The frontier posts, at the author’s request.</b> Four towns that served as frontier posts (thughūr), where Muslims stood guard (ribāṭ), lie inside V2: Ashkelon (ʿAsqalān, in today’s Israel), Alexandria (Egypt), Tarsus (Türkiye) and Qazvin (Iran). The author’s source attributes their praise to Ibn Taymiyya’s Majmūʿ al-Fatāwā; a section there on travelling to Ashkelon was found, but the passage naming all four was not checked.</p><p><b>Turkmenistan, Afghanistan and Pakistan, whole, and Greater Khurāsān at its widest (Versions 84–87).</b> At the author’s request V2 holds Iran, Turkmenistan, Afghanistan and Pakistan, each whole by today’s borders, and on top of them Greater Khurāsān at its widest: everything that any of three maps the author supplied shades as Khurāsān, with nothing cut. <b>How big Khurāsān was.</b> In the strict sense Khurāsān ran from Qūmis and Dāmghān, “the first city of Khurāsān” (al-Yaʿqūbī), along the northern edge of the great salt desert, to the Oxus (the Amu Darya) in the north-east and Badakhshān in the east, with Sīstān and Kirmān outside it to the south; it was divided into four quarters, round Nīshāpūr, Marw, Harāt and Balkh. Ibn Ḥawqal puts its limits at the Oxus, at Jarm in Badakhshān and at Dāmghān, and Yāqūt leaves Transoxiana and Khwārazm out of it. In a looser usage the name went much further: al-Yaʿqūbī stretches it from Rayy to Farghāna, Qudāma b. Jaʿfar lists Samarqand, Shāsh, Farghāna, Usrūshana, Khwārazm and Isbījāb among its cities, and al-Balādhurī counts Khwārazm, Ṭukhāristān, Sīstān and Transoxiana in it; Yāqūt explains that these were under the governor of Khurāsān rather than inside it. (Classical geographers as reported in <i>Encyclopaedia Iranica</i>, “Khorasan i. The Concept of Khorasan”, by R. Rante and M. Labbaf-Khaniki, and “Mā warāʾ al-nahr”, by C. E. Bosworth, both read in full; and Wikipedia, “Khorasan”. The geographers’ own texts were not read.) Modern historians put the wide sense in the same terms: Ann Lambton writes that in the early centuries of Islam Khurāsān “generally included all the Muslim provinces east of the Great Desert”, with Transoxiana, Sijistān and Quhistān, its Central Asian boundary “the Chinese desert and the Pamirs” and its Indian boundary along the Hindu Kush (<i>Continuity and Change in Medieval Persia</i>, 1988, p. 404, as quoted in Wikipedia, “Khorasan”, checked again in Version 134); <i>Britannica</i> gives the historical region from the Amu Darya west to the Caspian and from the edge of the central Iranian deserts east to the mountains of central Afghanistan, and notes that Arab geographers spoke of it reaching the borders of India. No classical or modern source gives its area. Measured by me: the strict sense (to the Oxus, on the author’s first map) about 1.16 million km² of land; the widest of his three maps about 1.88 million km²; the wide sense of Lambton and al-Yaʿqūbī, adding all of Transoxiana as his maps draw it, about 2.06 million km². On the author’s first map (Khurāsān to the Oxus) it measures about 1.16 million km². The widest of his maps, a “Greater Khorasan” map drawn on today’s provinces, and a third, rougher map add the looser sense across the Oxus: together the three come to about 1.88 million km², about 641,000 km² in Afghanistan, 396,000 in Iran, 352,000 in Turkmenistan, 266,000 in Uzbekistan, 142,000 in Tajikistan (all of it), 41,000 in Kyrgyzstan (Batken and parts of Osh and Jalal-Abad), 28,000 in Kazakhstan (by Tashkent and the Syr Darya), 6,900 in Pakistan, 4,800 in China (along the border, partly the rough map’s error) and 4,700 km² of the south-east Caspian (that water is out again since Version 109, so the outline follows the shore). Where the maps cover a province almost wholly (99% or more) the whole province is taken. The third map is small and blurred, so its edges are good only to some tens of km (my measurement). <b>Natural frontiers (Version 92).</b> At the author’s request, where V2’s edge crossed open land it was moved out (first as V2N, V2 with natural frontiers, side by side with V2 from Version 93; since Version 116 V2 has the same frontiers and in Version 118 the two were merged) to the nearest strong natural barrier (my choice of barriers; land was only added): in the Punjab, from today’s Pakistan–India line across the open plain to the Beas and Sutlej rivers (India’s Amritsar, Tarn Taran and Gurdaspur, about 8,700 km²); round the Farghāna valley, to the crests of the Chatkal, Fergana and Alay ranges (Kyrgyzstan’s Osh and Jalal-Abad regions whole, about 40,000 km² more); and in southern Kazakhstan, to the Karatau range and the Moyynkum and Kyzylkum sands (the Turkistan region whole, with Isbījāb, Otrār and Ṭarāz; about 95,000 km² more). Elsewhere V2’s land edge already follows seas, the Sahara, the Nile–Congo watershed, the lakes and the Rwenzori, the Ruvuma, the Caucasus crest, the Karakum and Kyzylkum, and the Pamirs and Karakoram. <b>Crests traced on height data (Version 95).</b> At the author’s request the mountain frontiers were then traced on real elevation data (Mapzen’s terrain tiles, built from SRTM and other surveys, in cells about 0.4 km across): the ring of crests round the Farghāna valley (the Chatkal, Kurama, Fergana, Alay and Turkestan ranges) and the Karatau’s divide between the Syr Darya side and the Chu–Talas side. V2N (V2 with these natural frontiers, Versions 93–117) already held nearly all the land inside them. What it did not yet hold was added: the Syr Darya side of the Karatau’s north-west end, from the Turkistan region’s edge to the tip of the range and down to the Syr Darya (about 7,000 km² of the Qyzylorda region), three pockets of the range’s south-east end (about 760 km² of the Zhambyl region), and three slivers of the Farghāna rim (about 45 km², most of them on the Chinese side of today’s border). Land it held beyond the crests was kept: about 33,000 km² of Kyrgyzstan beyond the Farghāna crests (for example the Chatkal valley, the Toktogul side of the Naryn and the Alay valley) and about 41,000 km² of the Turkistan region north of the Karatau (the Moyynkum sands to the Chu). The crest lines are my tracing (two floods on the height grid meet on the divide), good to about half a kilometre on the ridges; the Syr Darya is Natural Earth’s river line. Since Versions 116 and 117 the land between the Amu Darya and the Syr Darya and most of Khwārazm (Khiva, Nukus) are inside too; the rest of Kazakhstan, the Ustyurt and northern Kyrgyzstan are out of V2; V5, V6 and V7 hold them. For the eastern lands the author’s source cites the hadith “If faith were at the Pleiades, men from among these would attain it” (Ṣaḥīḥ Muslim 2546). In Muslim’s narration the Prophet ﷺ said it with his hand on Salmān al-Fārisī, so “these” are Salmān’s people, the Persians; reading it as praise of other eastern lands is the source’s reading, not the hadith’s wording. The source’s reference to al-Aḥkām al-Kubrā was not checked.</p>`,
  west: `<p>${CX_SPEC} <b>V3</b> is V5 stopping at Iraq’s eastern border; north of Iraq, Türkiye’s eastern border forms the edge. It holds the best-lands outline and adds ${CX_CORE3(false)}. Left out: Iran (with Khuzestan and ʿIrāq al-ʿAjam), Georgia, Armenia and Azerbaijan, Derbent and the Dagestan coast, Central Asia, Afghanistan and Pakistan.</p>`,
  gme: `<p>${CX_SPEC} <b>V7</b>, the largest outline, is the whole of V5, drawn in the same colour as one territory, extended to the Muslim-majority countries of Africa (${AFR_NAMES}), and every land beyond them that a caliphate once ruled, taking only the part that was ruled, with Austria, Slovenia, Andorra and the rest of Italy, France, Croatia, Hungary, Ukraine and the south of Russia added to join those lands up. V5, which it contains, holds the best-lands outline and adds ${CX_CORE3(true)}.</p>`
};
/* Version 108: V2-B is V2 without the Balkan Peninsula (V2 as it was in Version 106); its note is V2's without the Balkan paragraph */
CX_LEAD.fullb = CX_LEAD.full.replace(/<p><b>The Balkan Peninsula \(Version 107\)[\s\S]*?<\/p>/, '')
  .replace(/<p><b>Towns and villages on the line \(Version 106\)[\s\S]*?<\/p>/, () => `<p><b>Towns and villages on the line (Version 106), at the author’s request.</b> No town, village or neighbourhood is cut by V2-B’s own lines. Where the author’s line ran through a settlement, it goes round it and the whole settlement is inside: about 177 settlements it cut (among them Pathankot and Kathua in India, Osh, the Turtkul–Beruniy oasis on the Amu Darya, Shovot and Burlak in Uzbekistan, and villages in Kyrgyzstan and Kazakhstan), with about 530,000 people who were on the outer side, and 40 neighbouring villages that the redrawn line touched (about 30,000 people); about 480 km² in all (V2’s figures without its Balkan line, since V2-B took V2N’s frontiers in Version 116; my arithmetic). In China the line crosses no settlement. Found with Meta’s High Resolution Settlement Layer (people per ~30 m cell; houses less than ~90 m apart counted as one settlement) and Overture Maps for real borders and names (my method; the people are grid estimates, not a census). Where V2-B follows an existing international border it divides no one newly; about 205 places have grown together across those borders (for example Goma and Gisenyi, Bukavu and Rusizi, Tunduma and Nakonde, and Mahagi and Aru on the Congo–Uganda border); they are listed in the project’s report as of Version 106 but not changed.</p>`)
  .replace(CX_CORE(true), CX_CORE(true, false, true))
  .replace('<b>V2</b> (called Complete, or V1, before Version 66) holds', '<b>V2-B</b> is V2 without the Balkan Peninsula (Version 108, at the author’s request: V2 as it was before Version 107, with Greece and all of Türkiye still in, as he chose). Like V2 (called Complete, or V1, before Version 66) it holds')
  .replace('At the author’s request V2 holds Greater Turkey', 'At the author’s request V2-B holds Greater Turkey')
  .replace('Bulgaria and North Macedonia are back, whole, since Version 107, as part of the Balkan Peninsula (below). ', 'Bulgaria and North Macedonia are in V2 since Version 107, with the Balkan Peninsula, but not in V2-B. ');

const CX_IRAQ = {
  in: `<p><b>How I read "Greater Iraq".</b> Both readings are included: Khuzestan (al-Ahwāz), the modern irredentist claim, and ʿIrāq al-ʿAjam, the "Persian Iraq" of the later geographers, which is the old Jibāl of western Iran (Hamadān, Iṣfahān, Rayy, Qum, Qazvīn, Kirmānshāh). With the whole of Iran inside the outline, they add no land of their own; their names stay on the map to show where they lie.</p>`,
  out: `<p><b>How I read "Greater Iraq".</b> Both readings, Khuzestan (al-Ahwāz) and ʿIrāq al-ʿAjam (the old Jibāl of western Iran), lie in today’s Iran, so this version leaves them out.</p>`
};
const CX_SRC = (iran, nat, v3)=> `<p><b>What the sources say about the added lands.</b> The atlas finds no established sacred status for most of them; their place in Islamic history is conquest history, not a status. Ibn Kathīr, on 24:55, lists Cyprus among the lands taken in ʿUthmān's time; for Türkiye, the old Bilād al-Rūm${nat ? ' (in this version the Bosphorus is the line, so Istanbul’s European half is outside)' : ' with Istanbul on both sides of the Bosphorus'}, the hadith praise an army, not the land (al-Bukhārī 2924; Muslim 2897). Libya was conquered under the Rashidun from 642–643${v3 ? '' : '; Tunisia is the old Ifrīqiya, and Ibn Kathīr, on 24:55, counts Kairouan, in Tunisia, among the lands of the west conquered in ʿUthmān’s time'}, Greece was Ottoman for centuries, and northern Uganda (Equatoria) was held by Egypt under the Ottomans, 1870s–1889 (general knowledge). The rest of Uganda, and Kenya, Tanzania, Rwanda and Burundi, are inside only so that the whole Nile lies inside, at the author’s request; this atlas counts no caliphate’s rule there.${v3 ? " The island of Arwād off Ṭarṭūs was taken in ʿUthmān’s time (649–650) and razed; Muslims settled there only later, under Muʿāwiyah." : ''}${iran ? " Iran is the old land of Fāris and the Jibāl: Ibn Kathīr, on 24:55, describes most of Persia taken under ʿUmar, and Khurāsān and al-Ahwāz under ʿUthmān. The South Caucasus, the old Armenia and Arrān, has no status in the sources either, and most people in Georgia and Armenia are Christian." + (iran ? " Derbent (Bāb al-Abwāb), the gate between the Caucasus and the Caspian, was taken in 22/643 under ʿUmar, as modern histories also date it (Ibn Kathīr’s note on 24:55 does not name it)." : "") + " Turkmenistan, Afghanistan and Pakistan are roughly the old Khurāsān with part of Khwārazm, and al-Sind with its borderlands: Ibn Kathīr, on 24:55, names Khurāsān among the lands conquered under ʿUthmān, and modern historians date the conquest of Sind to the Umayyads, around 711–714 (the region names and the Sind date are from general knowledge)." : ''}${v3 ? " In the west, Ibn Kathīr, on 24:55, says that under ʿUthmān “the lands of the west were conquered as far as Cyprus and Andalusia, Kairouan and Sebta” (Kairouan is in Tunisia, the old Ifrīqiya; Sebta is Ceuta, on Morocco’s north coast). Modern historians (general knowledge, not checked for this atlas) put the lasting conquest of the Maghrib beyond Ifrīqiya, and of al-Andalus, under the Umayyads (about 670–711), and count ʿUthmān’s western campaigns and the raid on Sicily (652) as raids rather than rule. Sicily and Malta came under the Aghlabids (from 827 and 870)" + (iran ? ", and Transoxiana with Farghāna (Uzbekistan, Tajikistan and Kyrgyzstan) under the Umayyads, by Qutayba b. Muslim in the reign of al-Walīd I (705–715; this date checked in Wikipedia, “Muslim conquest of Transoxiana”)" : "") + "." : ''} For al-Ḥabashah the Sunnah says the opposite of a claim: "Let the Abyssinians alone as long as they let you alone" (Abū Dāwūd 4302; ḥasan according to al-Albānī).</p>`;
